"""Explain legacy regs, reliable and user wrappers and stack trace printing."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1961': ('출발 지점을 적은 쪽지를 안내소에 주었어요. 안내소가 준비되지 않아 안내문만 준다면 여행 기록은 늘어나지 않아요.', '출발 정보 전달과 weak 기본 함수의 빈 결과를 구별합니다.', 'skipnr=2 → skip=2를 쓰세요. nr_entries=0 → 경고만 하는 기본 함수 → nr_entries=0도 그리세요.', ['스택 추적은 함수가 다른 함수를 부르며 지나온 경로를 찾는 일이에요. regs는 CPU의 실행 상태를 저장한 정보의 위치를 가리켜요. 이 정보는 경로 찾기의 출발점으로 쓰이고, store는 찾은 주소를 넣을 배열이에요.', '여기서는 CONFIG_ARCH_STACKWALK가 꺼진 쪽의 stack_trace_save_regs를 읽어요. CONFIG는 커널을 만들 때 고르는 기능 설정이에요. 같은 함수 이름도 설정에 따라 다른 본문이 선택될 수 있어요.', '함수는 trace라는 준비 카드를 만들어요. entries에는 store를, max_entries에는 배열 용량 size를 넣어요. skip에는 skipnr를 그대로 넣으므로 2를 요청하면 2예요. 현재 스택을 찾는 다른 wrapper처럼 1을 더하지 않아요.', '이 중괄호 초기화에서 적지 않은 nr_entries는 0으로 시작해요. 이어서 save_stack_trace_regs(regs, &trace)를 불러 출발 정보와 카드 위치를 전달해요. &trace는 카드를 복사한 값이 아니라 원래 카드가 있는 위치예요.', '__weak 표시의 공통 기본 함수가 선택된 경우에는 미구현 경고만 내요. 실제 주소를 쓰거나 nr_entries를 바꾸지 않으므로, 경고 뒤 실행을 계속해 wrapper로 돌아오면 반환 개수는 0이에요. 용량이 4라고 결과가 자동으로 네 개 생기지는 않아요.', 'weak는 커널을 연결할 때 같은 이름의 강한 구현으로 대체될 수 있는 기본 정의예요. CPU별 실제 구현이 연결됐다면 그 코드를 따라가야 해요. 공통 기본 함수의 0 결과만 보고 모든 CPU가 이 기능을 지원하지 않는다고 결론내릴 수는 없어요.'], [('경고만 하는 기본 함수에서 돌아왔고 nr_entries를 바꾼 코드가 없다면 결과 개수는 얼마인가요?', ['준비한 배열 용량 전체예요', '처음 값인 0이에요'], '정답은 두 번째예요. nr_entries는 0으로 시작했고 기본 함수가 그대로 두었어요. 용량은 담을 수 있는 칸 수일 뿐 실제 기록 수가 아니에요.'), ('이 기본 경로에서 0이 나왔다고 모든 CPU가 regs 스택 추적을 못 한다고 할 수 있나요?', ['아니요. CPU별로 대신 연결되는 실제 구현을 확인해야 해요', '네. 기본 함수 하나를 보면 모든 CPU의 결과를 알 수 있어요'], '정답은 첫 번째예요. weak 기본 함수 대신 실제 기능을 가진 구현이 연결될 수 있어요. 지금 읽은 한 경로의 결과를 모든 기종의 결과로 넓히지 않아요.')]), 'os1962': ('검사하다 잘못된 부분을 발견했다면, 이미 몇 줄 적었어도 검사를 통과한 보고서라고 넘기면 안 돼요.', '신뢰성 검사 오류가 있으면 기록 개수보다 오류를 먼저 반환하는 이유를 이해합니다.', 'ret=0, 기록 3개 → 결과 3을 쓰세요. ret=-EIO, 기록 3개 → 결과 -EIO도 쓰세요.', ['reliable은 믿을 수 있는지 확인한다는 뜻이에요. 구형 stack_trace_save_tsk_reliable은 태스크의 호출 경로를 수집하면서 믿기 어려운 부분이 있는지 검사하는 내부 함수를 불러요. 이 본문은 구형 방식에서 reliable 지원 설정이 있을 때 사용해요.', '먼저 trace 카드의 entries에 결과 배열 위치를 넣고 max_entries에 용량을 넣어요. 생략한 정수 항목 skip과 nr_entries는 0으로 시작해요. skip은 처음에 건너뛸 개수예요. 이 함수에는 skipnr 입력 자체가 없으므로 skipnr+1을 넣는다고 읽으면 안 돼요.', 'save_stack_trace_tsk_reliable(tsk, &trace)의 결과를 int ret에 받아요. int는 음수도 담을 수 있는 정수 형식이에요. 내부 함수가 성공하면 ret는 0이고, 실패하면 음수 오류를 줘요. 저장한 개수는 별도로 trace.nr_entries에 있어요.', 'return ret ? ret : trace.nr_entries는 조건에 따라 둘 중 하나를 고르는 식이에요. 첫 ret가 0이 아니면 물음표 뒤의 ret를 고르고, 0이면 콜론 뒤의 기록 개수를 골라요. 그래서 오류가 있으면 그 오류를 호출한 쪽으로 전달해요.', '가령 세 주소를 적은 뒤 내부 함수가 -EIO를 주었다고 해 봐요. -EIO는 이 예제의 오류 표시이며, wrapper는 3이 아니라 -EIO를 반환해요. 일부 기록이 있다는 사실과 전체 경로를 믿을 수 있다는 판정은 달라요. 결과를 받는 쪽도 음수 오류를 먼저 확인해요.', '다른 태스크를 조사할 때는 호출하는 쪽이 그 태스크가 비활성이라는 조건을 마련해야 한다고 주석이 요구해요. 비활성은 그 태스크가 실행하며 스택을 바꾸고 있지 않은 상태를 뜻해요. 이 짧은 wrapper 자체가 태스크를 정지시키지는 않아요. 종이의 오류 선택 연습은 실제 CPU의 검사나 정지 절차를 실행한 것은 아니에요.'], [('세 주소를 적었더라도 내부 함수가 -EIO를 반환했다면 wrapper는 무엇을 돌려주나요?', ['오류를 버리고 기록 개수 3을 돌려줘요', '오류 -EIO를 돌려줘요'], '정답은 두 번째예요. ret가 0이 아니므로 ret ? ret : trace.nr_entries에서 ret를 골라요. 기록이 일부 남아 있어도 신뢰성 검사가 성공한 개수로 사용하면 안 돼요.'), ('이 함수의 구조체 초기화에서 생략된 skip은 어떤 값으로 시작하나요?', ['0이에요', '항상 skipnr+1이에요'], '정답은 첫 번째예요. 일부 항목만 지정한 구조체 초기화에서 생략된 정수 항목은 0이에요. 이 함수는 skipnr를 입력받지도 않으므로 다른 wrapper의 식을 가져오면 안 돼요.')]), 'os1963': ('접수 창구가 두 곳이면 확인하는 절차의 위치도 다를 수 있어요. 한 창구의 규칙이 다른 창구에도 적혀 있다고 가정하지 말고 실제 순서를 봐요.', '두 설정의 사용자 스택 wrapper를 구분하고 실제 기록 개수를 읽습니다.', '준비 카드 만들기 → save_stack_trace_user 호출 → nr_entries 반환을 그리세요. 용량 4, 실제 2개이면 결과 2라고 적으세요.', ['사용자 프로그램은 우리가 실행하는 일반 프로그램이고, 커널은 운영체제의 중심 코드예요. 사용자 스택 추적은 사용자 프로그램이 함수를 부르며 지나온 경로를 찾는 일이에요. 여기서는 CONFIG_ARCH_STACKWALK가 꺼진 구형 경로의 사용자 추적 함수를 읽어요.', 'CONFIG_USER_STACKTRACE_SUPPORT는 사용자 스택 추적 지원을 선택하는 설정이에요. 그 조건 아래의 stack_trace_save_user는 store라는 출력 배열 위치와 size라는 배열 용량을 받아요. 이 함수가 배열 공간을 새로 만드는 것은 아니에요.', '준비 카드 trace의 entries와 max_entries를 채워요. 중괄호 초기화에서 생략한 skip과 nr_entries는 0이에요. skip은 건너뛸 개수이고 nr_entries는 실제 저장 개수예요. 둘 다 0으로 시작해도 맡은 역할은 달라요.', '이 wrapper의 본문에는 PF_KTHREAD 검사가 없어요. PF_KTHREAD는 커널 스레드라는 표시예요. 앞서 본 ARCH_STACKWALK 쪽은 그 표시가 있으면 일찍 0을 반환하지만, 지금 본문에는 그 if 문이 없다는 점을 구별해요.', '지금 본문은 save_stack_trace_user(&trace)를 호출한 뒤 trace.nr_entries를 반환해요. 네 칸짜리 배열에 내부 함수가 두 주소를 적고 개수를 2로 기록했다면 결과는 2예요. max_entries=4는 공간의 한도이므로 그대로 결과 개수로 쓰지 않아요.', '이 wrapper에 검사문이 없다고 커널 스레드의 사용자 주소를 아무렇게나 읽어도 된다는 뜻은 아니에요. CPU별 내부 함수와 호출하는 쪽이 어떤 대상과 메모리 접근을 허용하는지 확인해야 해요. 여기서는 준비 정보 전달과 반환 순서를 배우며, 전체 접근 안전성은 관련 구현까지 함께 살펴요.'], [('지금 읽은 구형 사용자 wrapper 본문에 PF_KTHREAD 검사 뒤 바로 반환하는 코드가 있나요?', ['네. 다른 설정의 본문과 똑같이 있어요', '아니요. 이 본문에는 없어요'], '정답은 두 번째예요. 본문은 카드 준비, 내부 함수 호출, 개수 반환으로 이어져요. 다른 설정에서 본 검사문을 여기도 있다고 생각하면 실제 호출 순서를 놓쳐요.'), ('용량은 4이고 내부 함수가 기록한 nr_entries는 2라면 반환값은 무엇인가요?', ['실제 개수인 2예요', '용량 전체인 4예요'], '정답은 첫 번째예요. return 뒤에는 trace.nr_entries가 있어요. 준비한 네 칸을 모두 채웠다는 뜻이 아니므로 용량을 결과로 대신 쓰면 안 돼요.')]), 'os1964': ('찾아 둔 장소 번호를 이름표와 함께 한 줄씩 읽으면 경로를 알아보기 쉬워요. 이 함수는 이미 모아 둔 주소를 출력하는 일을 해요.', '출력 전 배열 확인, 들여쓰기 폭, 주소의 이름 표시를 이해합니다.', 'spaces=2이면 1+2=3개의 공백을 그리세요. 주소 두 개는 두 줄로 적고 NULL인 경우에는 출력 반복 전에 멈춘다고 표시하세요.', ['stack_trace_print는 이미 수집한 주소 배열을 커널 로그에 출력해요. 새로 호출 경로를 찾는 함수가 아니에요. entries는 배열 위치이고 nr_entries는 읽을 항목 수예요. 호출하는 쪽이 그 수만큼 읽을 수 있는 배열을 준비해야 해요.', '먼저 if (WARN_ON(!entries))를 확인해요. NULL은 가리키는 대상이 없다는 포인터 값이고 !entries는 그 경우 참이 돼요. 경고 뒤 실행이 계속되는 경우 바로 return하므로 배열을 읽는 반복으로 가지 않아요.', '배열 위치가 있다면 i=0부터 시작해 i < nr_entries인 동안 출력해요. 실제 개수가 2면 0번과 1번만 읽어요. 배열이 네 칸이어도 입력한 개수가 2라면 네 줄을 출력하지 않아요. NULL 검사는 모든 잘못된 주소나 과도한 개수까지 확인하는 검사는 아니에요.', 'printk의 %*c는 문자를 정해진 폭에 맞춰 출력하는 형식이에요. 여기서는 폭으로 1+spaces를 주고 문자로 공백 한 개를 줘요. 작은 음수 아닌 값으로 연습하면 spaces=2일 때 폭은 3이고 공백 세 칸이 나와요. 이름만 보고 언제나 spaces와 같은 칸 수라고 생각하지 않아요.', '%pS는 주소를 커널 심벌 이름과 위치 정보로 표시하는 형식이에요. 심벌은 함수 등에 붙은 이름이라고 생각하면 돼요. 숫자 주소만 보는 것보다 어느 코드인지 알아보기 쉬워요. KALLSYMS라는 이름 찾기 기능이 꺼져 있으면 주소로 표시되므로 항상 함수 이름이 나온다고 약속할 수는 없어요.', '마지막 \\n은 다음 줄로 넘어가라는 표시예요. 공백, 주소에 대한 표시, 줄바꿈을 항목마다 반복해요. 종이에 A 함수와 B 함수라고 이름을 대신 써 보는 활동은 순서와 들여쓰기 연습이며, 실제 커널의 이름 검색이나 로그 출력을 시험한 것은 아니에요.'], [('spaces=2를 주면 이 식이 %*c에 전달하는 폭은 얼마인가요?', ['2예요', '3이에요'], '정답은 두 번째예요. 코드가 1+spaces를 계산하므로 1+2=3이에요. 출력할 문자도 공백이어서 이 예에서는 공백 세 칸이 돼요.'), ('entries가 NULL일 때 경고 뒤 실행이 계속된다면 다음에 무엇을 하나요?', ['바로 반환해서 주소 출력 반복에 들어가지 않아요', '반드시 entries[0]부터 읽어요'], '정답은 첫 번째예요. 배열 검사 아래의 return이 반복문보다 먼저 실행돼요. 가리키는 배열이 없는데 첫 칸을 읽으려 하지 않아요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_486.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
